// Extract error data from n8n's built-in error workflow context
// When used as an Error Workflow, n8n provides error context automatically

// Get current timestamp
const timestamp = new Date().toISOString();

// Extract error information from n8n's error context
const errorContext = $input.first().json;
const workflowName = errorContext.workflow?.name || 'Unknown Workflow';
const errorMessage = errorContext.execution?.error?.message || 'No error message provided';
const nodeName = errorContext.execution?.lastNodeExecuted || 'Unknown Node'; // Use lastNodeExecuted for the node name
const errorType = errorContext.execution?.error?.name || errorContext.execution?.error?.type || 'General Error';

// Build workflow URL
const workflowId = errorContext.workflow?.id;
// Dynamically get the base URL from the execution URL
const baseUrl = errorContext.execution?.url ? errorContext.execution.url.split('/workflow')[0] : 'https://your-n8n-instance.com';
const workflowUrl = workflowId ? `${baseUrl}/workflow/${workflowId}` : 'URL not available';

// Format for Google Sheets
const sheetRow = {
  timestamp: timestamp,
  workflowName: workflowName,
  nodeName: nodeName,
  errorType: errorType,
  errorMessage: errorMessage,
  executionId: errorContext.execution?.id || 'Unknown',
  workflowUrl: workflowUrl
};

// Format for email
const emailData = {
  subject: `⚠️ n8n Workflow Error: ${workflowName}`,
  workflowName: workflowName,
  nodeName: nodeName,
  errorMessage: errorMessage,
  errorType: errorType,
  workflowUrl: workflowUrl,
  executionId: errorContext.execution?.id || 'Unknown',
  timestamp: new Date(timestamp).toLocaleString()
};

console.log('Error Context:', JSON.stringify(errorContext, null, 2));
console.log('Processed Data:', { sheetRow, emailData });

return {
  sheetData: sheetRow,
  emailData: emailData
};
